mapper.update:
update sys_work_calendar_year
set active_version_id = #{draftVersionId},
    draft_version_id = null,
    version = version + 1,
    update_by = #{operatorId},
    update_time = current_timestamp
where id = #{yearId}
  and version = #{expectedVersion}
  and draft_version_id = #{draftVersionId}
  and deleted = 0
